  function printableActPages(o,marked){if(actPageTemplates.length!==2)return originalActPages(o,marked);return actPageTemplates.map((html,index)=>{const template=document.createElement('template');template.innerHTML=html;const page=template.content,inputs=[...page.querySelectorAll('input')];inputs.forEach(input=>{const value=actData[input.name];if(input.type==='checkbox'){input.checked=!!value;value?input.setAttribute('checked',''):input.removeAttribute('checked')}else{input.value=value??'';input.setAttribute('value',value??'')}});const layer=page.querySelector('#damageMarkersLayer');if(layer){let markers=[];try{markers=JSON.parse(actData.damage_markers_json||'[]')}catch(e){}layer.innerHTML=markers.map(m=>`<div class="damage-marker" style="left:${Number(m.x)||0}%;top:${Number(m.y)||0}%">${esc(m.code||'')}</div>`).join('')}const oil=Number(actData.oil_level_percent),oilMarker=page.querySelector('#oilMarker'),oilValue=page.querySelector('#oilValue');if(oilMarker&&oilValue&&actData.oil_level_percent!==''){const x=17.72+41.9*Math.max(0,Math.min(100,oil))/100;oilMarker.style.left=x+'%';oilMarker.style.display='block';oilValue.style.left=x+'%';oilValue.style.display='block';oilValue.textContent=Math.round(oil)+'%'}page.querySelectorAll('.damage-hitbox,.oil-hitbox,input[type="hidden"]').forEach(x=>x.remove());return`<section class="original-act-page print-act-page" aria-label="Акт осмотра, лист ${index+1}">${template.innerHTML}</section>`})}
